#!/usr/bin/env python3
"""Apply the SafeVoice access-control and AllegroGraph-connection changes.

Run from the repository root:   python apply_safevoice_changes.py

Works on Windows (CRLF) and Linux/macOS (LF) checkouts: it keeps each file's own line endings.
It edits by exact text, so other people's changes in the same files are kept. It refuses to touch a
file whose text does not match what it expects (and writes nothing then). Running it twice is safe.
Add --check to only report what would happen.
"""
import os
import sys

