def read(path):
    raw = open(path, "rb").read().decode("utf-8")
    return raw, ("\r\n" if "\r\n" in raw else "\n")


def main(check_only):
    plan, problems = [], []
    for path, pairs in EDITS.items():
        if not os.path.exists(path):
            problems.append(f"{path}: file not found (run this from the repository root)")
            continue
        raw, eol = read(path)
        text, state = raw.replace("\r\n", "\n"), []
        for old, new in pairs:
            if text.count(new) >= 1 and text.count(old) == 0:
                state.append("done")
            elif text.count(old) == 1:
                text = text.replace(old, new)
                state.append("apply")
            else:
                problems.append(f"{path}: expected text not found exactly once near: {old.splitlines()[min(3, len(old.splitlines()) - 1)].strip()[:70]!r}")
                break
        else:
            plan.append((path, text.replace("\n", eol), state))
    for path, content in NEW_FILES.items():
        exists = os.path.exists(path)
        plan.append((path, content, ["exists" if exists else "create"]))
    if problems:
        print("NOTHING WAS CHANGED. Problems:")
        for p in problems:
            print("  -", p)
        print("Send me the current version of the file(s) above and I will adjust the changes.")
        return 1
    for path, content, state in plan:
        if "exists" in state:
            print(f"  skip   {path} (already exists; delete it first to replace it)")
        elif state and all(s == "done" for s in state):
            print(f"  ok     {path} (already applied)")
        else:
            print(f"  {'would change' if check_only else 'changed'} {path}")
            if not check_only:
                os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
                with open(path, "wb") as fh:
                    fh.write(content.encode("utf-8"))
    print("Done." if not check_only else "Check passed: all changes can be applied.")
    return 0


if __name__ == "__main__":
    sys.exit(main("--check" in sys.argv))